/* eslint-disable @next/next/no-img-element -- 1600w variant is pre-generated by the
   media pipeline and served from /api/media; next/image would add no value here. */
"use client";
import { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { Language, translate } from "@/lib/i18n/translations";

export type LightboxItem = { assetId: string; alt: string; caption?: string };

type Props = {
  items: LightboxItem[];
  index: number;
  onClose: () => void;
  onNavigate: (nextIndex: number) => void;
  lang: Language;
};

export function GalleryLightbox({ items, index, onClose, onNavigate, lang }: Props) {
  const closeRef = useRef<HTMLButtonElement>(null);
  const touchStartX = useRef<number | null>(null);

  useEffect(() => {
    closeRef.current?.focus();
  }, []);

  useEffect(() => {
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = ""; };
  }, []);

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      else if (e.key === "ArrowLeft" && index > 0) onNavigate(index - 1);
      else if (e.key === "ArrowRight" && index < items.length - 1) onNavigate(index + 1);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [index, items.length, onClose, onNavigate]);

  const item = items[index];
  if (!item) return null;

  return createPortal(
    <div
      role="dialog"
      aria-modal="true"
      aria-label={item.alt}
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/85 p-4"
      onClick={onClose}
      onTouchStart={(e) => { touchStartX.current = e.touches[0].clientX; }}
      onTouchEnd={(e) => {
        if (touchStartX.current == null) return;
        const dx = e.changedTouches[0].clientX - touchStartX.current;
        touchStartX.current = null;
        if (Math.abs(dx) < 50) return;
        if (dx > 0 && index > 0) onNavigate(index - 1);
        else if (dx < 0 && index < items.length - 1) onNavigate(index + 1);
      }}
    >
      <div className="relative max-h-full max-w-full" onClick={(e) => e.stopPropagation()}>
        <img src={`/api/media/${item.assetId}/1600`} alt={item.alt} className="max-h-[85vh] max-w-full rounded-lg object-contain" />
        {item.caption ? <p className="mt-2 text-center text-sm text-white/80">{item.caption}</p> : null}
        <p className="mt-1 text-center text-xs text-white/60">{translate(lang, "masterClass.lightbox.counter", { current: index + 1, total: items.length })}</p>
        <button ref={closeRef} type="button" onClick={onClose} aria-label={translate(lang, "masterClass.lightbox.close")} className="absolute -top-10 right-0 flex h-9 w-9 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white/20 sm:-right-12 sm:top-0">✕</button>
        {index > 0 ? (
          <button type="button" onClick={() => onNavigate(index - 1)} aria-label={translate(lang, "masterClass.lightbox.prev")} className="absolute left-2 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white/20">‹</button>
        ) : null}
        {index < items.length - 1 ? (
          <button type="button" onClick={() => onNavigate(index + 1)} aria-label={translate(lang, "masterClass.lightbox.next")} className="absolute right-2 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white/20">›</button>
        ) : null}
      </div>
    </div>,
    document.body
  );
}
